<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import dayjs from 'dayjs';import { ElMessage } from 'element-plus';import { http } from '../api/http';
type Department={id:number;name:string;_count:{users:number}};type AdminUser={id:number;username:string;name:string;email:string;role:string;active:boolean;department?:{name:string}};type Log={id:number;action:string;entityType:string;detail:string;createdAt:string;user:{name:string}};
const active=ref('users');const users=ref<AdminUser[]>([]);const departments=ref<Department[]>([]);const logs=ref<Log[]>([]);const rule=reactive({minAdvanceMinutes:0,maxDurationMinutes:480,checkInEarlyMinutes:15,noShowMinutes:30});const userDialog=ref(false);const deptName=ref('');const userForm=reactive({username:'',password:'Demo@123',name:'',email:'',role:'EMPLOYEE',departmentId:null as number|null});
async function load(){const [u,d,l,r]=await Promise.all([http.get('/admin/users'),http.get('/admin/departments'),http.get('/admin/logs'),http.get('/admin/rules')]);users.value=u.data;departments.value=d.data;logs.value=l.data;Object.assign(rule,r.data)}async function saveRule(){await http.put('/admin/rules',rule);ElMessage.success('预约规则已保存')}async function addDept(){await http.post('/admin/departments',{name:deptName.value});deptName.value='';ElMessage.success('部门已添加');load()}async function addUser(){await http.post('/admin/users',userForm);userDialog.value=false;ElMessage.success('用户已创建');load()}onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2>系统管理</h2><p>管理用户、部门、预约策略和操作审计记录</p></div></div><section class="panel"><el-tabs v-model="active"><el-tab-pane label="用户管理" name="users"><div class="toolbar"><el-button type="primary" @click="userDialog=true">+ 新增用户</el-button></div><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="name" label="姓名"/><el-table-column prop="department.name" label="部门"/><el-table-column prop="email" label="邮箱" min-width="180"/><el-table-column label="角色"><template #default="s"><el-tag>{{s.row.role==='ADMIN'?'管理员':'员工'}}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.active?'success':'info'">{{s.row.active?'启用':'停用'}}</el-tag></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="部门管理" name="departments"><div class="toolbar"><el-input v-model="deptName" placeholder="新部门名称" style="width:260px"/><el-button type="primary" @click="addDept">添加部门</el-button></div><el-table :data="departments"><el-table-column prop="name" label="部门名称"/><el-table-column prop="_count.users" label="成员数量"/><el-table-column prop="id" label="部门编号"/></el-table></el-tab-pane><el-tab-pane label="预约规则" name="rules"><el-form :model="rule" label-width="160px" style="max-width:560px;padding-top:15px"><el-form-item label="最少提前预约"><el-input-number v-model="rule.minAdvanceMinutes" :min="0"/><span class="unit">分钟</span></el-form-item><el-form-item label="单次最长时长"><el-input-number v-model="rule.maxDurationMinutes" :min="30"/><span class="unit">分钟</span></el-form-item><el-form-item label="允许提前签到"><el-input-number v-model="rule.checkInEarlyMinutes" :min="0"/><span class="unit">分钟</span></el-form-item><el-form-item label="超时未签到判定"><el-input-number v-model="rule.noShowMinutes" :min="5"/><span class="unit">分钟</span></el-form-item><el-form-item><el-button type="primary" @click="saveRule">保存预约规则</el-button></el-form-item></el-form></el-tab-pane><el-tab-pane label="操作日志" name="logs"><el-table :data="logs"><el-table-column label="时间" width="170"><template #default="s">{{dayjs(s.row.createdAt).format('YYYY-MM-DD HH:mm')}}</template></el-table-column><el-table-column prop="user.name" label="操作人" width="120"/><el-table-column prop="action" label="动作" width="110"/><el-table-column prop="entityType" label="对象" width="110"/><el-table-column prop="detail" label="操作详情"/></el-table></el-tab-pane></el-tabs></section>
<el-dialog v-model="userDialog" title="新增系统用户" width="520px"><el-form :model="userForm" label-width="80px"><el-form-item label="用户名"><el-input v-model="userForm.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="userForm.name"/></el-form-item><el-form-item label="邮箱"><el-input v-model="userForm.email"/></el-form-item><el-form-item label="初始密码"><el-input v-model="userForm.password" show-password/></el-form-item><el-form-item label="部门"><el-select v-model="userForm.departmentId" style="width:100%"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="角色"><el-radio-group v-model="userForm.role"><el-radio value="EMPLOYEE">员工</el-radio><el-radio value="ADMIN">管理员</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="userDialog=false">取消</el-button><el-button type="primary" @click="addUser">创建用户</el-button></template></el-dialog></div></template><style scoped>.unit{margin-left:10px;color:#8d97a8}.el-tabs{min-height:500px}</style>
